    ('6f0243f4-f23c-5a77-8bbb-f7b42d2d6a49'::uuid, 'Structures de données'),
    ('3d703ba2-2d27-507d-bd31-d34d6f65c70c'::uuid, 'Structures de données'),
    ('897a1e61-6e4d-5956-ad5b-0a61efec0a8f'::uuid, 'Bases de données'),
    ('a6cbec5f-3b81-5309-82ac-890fb4bfafbf'::uuid, 'Bases de données'),
    ('8d5c9ba0-28e9-5b11-a1ad-06876a0996a3'::uuid, 'Bases de données'),
    ('0a6a401e-ab19-5fef-bf93-70b308c48489'::uuid, 'Bases de données'),
